// Anti-aliased bitmap fonts (generated by tools/gen_font.py).
#pragma once

#include <stdint.h>

typedef struct {
  uint8_t w, h;         // cell size in pixels
  uint8_t first, last;  // character codes covered
  const uint8_t *bits;  // 4-bit coverage, w*h/2 bytes per glyph
} font_t;

extern const font_t font_s;  // 8x16, regular
extern const font_t font_l;  // 12x24, bold

// Extra symbols (codes 0x80..), use with string concatenation: "CH0" G_UP
#define G_UP     "\x80"  // rising edge
#define G_DOWN   "\x81"  // falling edge
#define G_MICRO  "\x82"
#define G_TIMES  "\x83"
#define G_DOT    "\x84"
#define G_UPDOWN "\x85"
#define G_DELTA  "\x86"
